//Тикет - ISS-2025-01030
//Кастомный Серверный метод необходим из-за сложностей обращения к дочерней таблице в Supplier
function checkUserAffiliation(frm, user) {
    return new Promise((resolve) => {
        if (!user) {
            resolve({ exists: false });
            return;
        }

        frappe.call({
            method: 'check_user_affiliation.process_check',
            args: { user: user },
            callback: ({ message }) => {
                if (!message.is_employee && !message.is_supplier) {
                    frappe.msgprint({
                        title: __('Внимание!'),
                        indicator: 'red',
                        message: __('Участник не найден ни как Сотрудник, ни как Поставщик')
                    });
                }
                resolve(message);
            }
        });
    });
}

// Применение в обработчике
frappe.ui.form.on('Project Team Details', {
    pt_participant: async function(frm, cdt, cdn) {
        const child = frappe.get_doc(cdt, cdn);
        await checkUserAffiliation(frm, child?.pt_participant);
    }
});
